theorem Std.TreeSet.maxD_eq_iff_mem_and_forall.{u} {α : Type u} {cmp : α → α → Ordering}
  {t : Std.TreeSet α cmp} [Std.TransCmp cmp] [Std.LawfulEqCmp cmp] (he : t.isEmpty = false)
  {km fallback : α} : t.maxD fallback = km ↔ km ∈ t ∧ ∀ k ∈ t, (cmp k km).isLE = true

theorem Std.TreeSet.Equiv.getGT_eq.{u} {α : Type u} {cmp : α → α → Ordering} {t₁ t₂ : Std.TreeSet α cmp}
  [Std.TransCmp cmp] {k : α} {h' : ∃ a ∈ t₁, cmp a k = Ordering.gt} (h : t₁.Equiv t₂) :
  t₁.getGT k h' = t₂.getGT k ⋯

