  (contains_eq_false : (List.map Prod.fst l).contains k = false) :
  (m.insertMany l).getKey! k = m.getKey! k

theorem Std.HashMap.Raw.get?_union_of_not_mem_left.{u, v} {α : Type u} [BEq α] [Hashable α] {β : Type v}
  {m₁ m₂ : Std.HashMap.Raw α β} [EquivBEq α] [LawfulHashable α] (h₁ : m₁.WF) (h₂ : m₂.WF) {k : α}
  (not_mem : k ∉ m₁) : (m₁ ∪ m₂).get? k = m₂.get? k

theorem Std.HashMap.Raw.getElem?_diff.{u, v} {α : Type u} [BEq α] [Hashable α] {β : Type v}
  {m₁ m₂ : Std.HashMap.Raw α β} [EquivBEq α] [LawfulHashable α] (h₁ : m₁.WF) (h₂ : m₂.WF) {k : α} :
  (m₁ \ m₂)[k]? = if k ∈ m₂ then none else m₁[k]?

theorem Std.HashMap.Raw.isEmpty_insertMany_list.{u, v} {α : Type u} {β : Type v} {m : Std.HashMap.Raw α β}
  [BEq α] [Hashable α] [EquivBEq α] [LawfulHashable α] (h : m.WF) {l : List (α × β)} :
  (m.insertMany l).isEmpty = (m.isEmpty && l.isEmpty)

theorem Std.HashMap.Raw.mem_of_mem_insertManyIfNewUnit_list.{u} {α : Type u} [BEq α] [Hashable α]
  {m : Std.HashMap.Raw α Unit} [EquivBEq α] [LawfulHashable α] (h : m.WF) {l : List α} {k : α}
  (contains_eq_false : l.contains k = false) : k ∈ m.insertManyIfNewUnit l → k ∈ m

theorem Std.HashMap.Raw.getKeyD_union_of_not_mem_right.{u, v} {α : Type u} [BEq α] [Hashable α] {β : Type v}
  {m₁ m₂ : Std.HashMap.Raw α β} [EquivBEq α] [LawfulHashable α] (h₁ : m₁.WF) (h₂ : m₂.WF)
  {k fallback : α} (not_mem : k ∉ m₂) : (m₁ ∪ m₂).getKeyD k fallback = m₁.getKeyD k fallback

theorem Std.HashMap.Raw.getElem!_insertMany_list_of_mem.{u, v} {α : Type u} {β : Type v}
  {m : Std.HashMap.Raw α β} [BEq α] [Hashable α] [EquivBEq α] [LawfulHashable α] [Inhabited β]
  (h : m.WF) {l : List (α × β)} {k k' : α} (k_beq : (k == k') = true) {v : β}
  (distinct : List.Pairwise (fun a b => (a.1 == b.1) = false) l) (mem : (k, v) ∈ l) :
  (m.insertMany l)[k']! = v

theorem Std.HashMap.Raw.getElem?_insert_self.{u, v} {α : Type u} {β : Type v} {m : Std.HashMap.Raw α β}
  [BEq α] [Hashable α] [EquivBEq α] [LawfulHashable α] (h : m.WF) {k : α} {v : β} :
  (m.insert k v)[k]? = some v

theorem Std.HashMap.Raw.getKey_insert_self.{u, v} {α : Type u} {β : Type v} {m : Std.HashMap.Raw α β}
  [BEq α] [Hashable α] [EquivBEq α] [LawfulHashable α] (h : m.WF) {k : α} {v : β} :
  (m.insert k v).getKey k ⋯ = k

theorem Std.HashMap.Raw.getKey!_congr.{u, v} {α : Type u} {β : Type v} {m : Std.HashMap.Raw α β} [BEq α]
  [Hashable α] [EquivBEq α] [LawfulHashable α] [Inhabited α] (h : m.WF) {k k' : α}
  (h' : (k == k') = true) : m.getKey! k = m.getKey! k'

theorem Std.HashMap.Raw.get_union_of_not_mem_right.{u, v} {α : Type u} [BEq α] [Hashable α] {β : Type v}
  {m₁ m₂ : Std.HashMap.Raw α β} [EquivBEq α] [LawfulHashable α] (h₁ : m₁.WF) (h₂ : m₂.WF) {k : α}
  (not_mem : k ∉ m₂) {h' : k ∈ m₁ ∪ m₂} : (m₁ ∪ m₂).get k h' = m₁.get k ⋯

theorem Std.HashMap.Raw.contains_diff.{u, v} {α : Type u} [BEq α] [Hashable α] {β : Type v}
  {m₁ m₂ : Std.HashMap.Raw α β} [EquivBEq α] [LawfulHashable α] (h₁ : m₁.WF) (h₂ : m₂.WF) {k : α} :
  (m₁ \ m₂).contains k = (m₁.contains k && !m₂.contains k)

theorem Std.HashMap.Raw.getElem?_diff_of_not_mem_left.{u, v} {α : Type u} [BEq α] [Hashable α] {β : Type v}
  {m₁ m₂ : Std.HashMap.Raw α β} [EquivBEq α] [LawfulHashable α] (h₁ : m₁.WF) (h₂ : m₂.WF) {k : α}
  (not_mem : k ∉ m₁) : (m₁ \ m₂)[k]? = none

theorem Std.HashMap.Raw.getD_eq_fallback_of_contains_eq_false.{u, v} {α : Type u} {β : Type v}
  {m : Std.HashMap.Raw α β} [BEq α] [Hashable α] [EquivBEq α] [LawfulHashable α] (h : m.WF) {a : α}
  {fallback : β} : m.contains a = false → m.getD a fallback = fallback

theorem Std.HashMap.Raw.getElem?_inter_of_mem_right.{u, v} {α : Type u} [BEq α] [Hashable α] {β : Type v}
  {m₁ m₂ : Std.HashMap.Raw α β} [EquivBEq α] [LawfulHashable α] (h₁ : m₁.WF) (h₂ : m₂.WF) {k : α}
  (mem : k ∈ m₂) : (m₁ ∩ m₂)[k]? = m₁[k]?

theorem Std.HashMap.Raw.getKey!_inter.{u, v} {α : Type u} [BEq α] [Hashable α] {β : Type v}
  {m₁ m₂ : Std.HashMap.Raw α β} [EquivBEq α] [LawfulHashable α] [Inhabited α] (h₁ : m₁.WF)
  (h₂ : m₂.WF) {k : α} : (m₁ ∩ m₂).getKey! k = if k ∈ m₂ then m₁.getKey! k else default

theorem Std.HashMap.Raw.get?_eq_some_iff_exists_beq_and_mem_toArray.{u, v} {α : Type u} {β : Type v}
  {m : Std.HashMap.Raw α β} [BEq α] [Hashable α] [EquivBEq α] [LawfulHashable α] {k : α} {v : β}
  (h : m.WF) : m.get? k = some v ↔ ∃ k', (k == k') = true ∧ (k', v) ∈ m.toArray

theorem Std.HashMap.Raw.mem_of_mem_insertIfNew.{u, v} {α : Type u} {β : Type v} {m : Std.HashMap.Raw α β}
  [BEq α] [Hashable α] [EquivBEq α] [LawfulHashable α] (h : m.WF) {k a : α} {v : β} :
  a ∈ m.insertIfNew k v → (k == a) = false → a ∈ m

theorem Std.HashMap.Raw.getD_filterMap'.{u, v, w} {α : Type u} {β : Type v} {γ : Type w} [BEq α]
  [Hashable α] {m : Std.HashMap.Raw α β} [LawfulBEq α] {f : α → β → Option γ} {k : α} {fallback : γ}
  (h : m.WF) : (Std.HashMap.Raw.filterMap f m).getD k fallback = (m[k]?.bind (f k)).getD fallback

theorem Std.HashMap.Raw.any_eq_true_iff_exists_mem_getElem.{u, v} {α : Type u} {β : Type v}
  {m : Std.HashMap.Raw α β} [BEq α] [Hashable α] [LawfulBEq α] {p : α → β → Bool} (h : m.WF) :
  m.any p = true ↔ ∃ a, ∃ (h : a ∈ m), p a m[a] = true

theorem Std.HashMap.Raw.not_mem_inter_of_not_mem_left.{u, v} {α : Type u} [BEq α] [Hashable α] {β : Type v}
  {m₁ m₂ : Std.HashMap.Raw α β} [EquivBEq α] [LawfulHashable α] (h₁ : m₁.WF) (h₂ : m₂.WF) {k : α}
  (not_mem : k ∉ m₁) : k ∉ m₁ ∩ m₂
